def minGraphColors(n, edges):
    if not edges:
        return 1
    adj = [0] * n
    for u, v in edges:
        adj[u] |= 1 << v
        adj[v] |= 1 << u
    deg = [bin(a).count("1") for a in adj]
    color = [-1] * n

    def feasible(k):
        for v in range(n):
            color[v] = -1

        def go(done, used):
            if done == n:
                return True
            best, best_key, best_seen = -1, (-1, -1), 0
            for v in range(n):
                if color[v] < 0:
                    seen = 0
                    a = adj[v]
                    while a:
                        low = a & -a
                        a ^= low
                        c = color[low.bit_length() - 1]
                        if c >= 0:
                            seen |= 1 << c
                    key = (bin(seen).count("1"), deg[v])
                    if key > best_key:
                        best, best_key, best_seen = v, key, seen
            options = ((1 << min(used + 1, k)) - 1) & ~best_seen
            while options:
                low = options & -options
                options ^= low
                c = low.bit_length() - 1
                color[best] = c
                if go(done + 1, max(used, c + 1)):
                    return True
            color[best] = -1
            return False

        return go(0, 0)

    k = 2
    while not feasible(k):
        k += 1
    return k
